// El token ya lo verifica el nodo del webhook (Header Auth).
// La ficha y el historial vienen armados desde Netlify (chat.js).
const cuerpo = $input.first().json.body || {};
const c = cuerpo.contexto || {};

return [{
  json: {
    usuario_id: cuerpo.usuario_id,
    mensaje: cuerpo.mensaje,
    fecha_hoy: c.fecha_hoy || '',
    ficha: c.ficha_texto || 'Sin datos del usuario.',
    ultimas_sesiones: c.sesiones_texto || 'Todavía no registró ninguna sesión.'
  }
}];
